from __future__ import annotations

import base64
from pathlib import Path

HELPER = ""
TEST = ""
EXCERPT = "ICAgICAgICBsZXQgZXhjZXJwdCA9IHJlbmRlcl9weXRob25fc2VsZWN0aW9uX3dpdGhfYW5jaG9ycygKICAgICAgICAgICAgc3JjLAogICAgICAgICAgICB0ZXh0LAogICAgICAgICAgICAmc2VudGVuY2VzLAogICAgICAgICAgICAmY2hvc2VuLAogICAgICAgICAgICBmaWxlX2J1ZGdldCwKICAgICAgICApOwo="

path = Path("entroly-qccr/src/lib.rs")
text = path.read_text(encoding="utf-8")
helper = base64.b64decode(HELPER).decode()
test = base64.b64decode(TEST).decode()
excerpt = base64.b64decode(EXCERPT).decode()
marker = "fn approx_tokens(s: &str) -> usize {\n    (s.chars().count() / CHARS_PER_TOKEN).max(1)\n}\n"
old_excerpt = "        let excerpt = chosen\n            .iter()\n            .map(|&i| sentences[i].clone())\n            .collect::<Vec<_>>()\n            .join(\"\\n\");\n"
test_marker = "    #[test]\n    fn split_sentences_breaks_on_boundaries() {\n"
for label, needle in (("approx_tokens", marker), ("excerpt", old_excerpt), ("test", test_marker)):
    if needle not in text:
        raise SystemExit(f"{label} marker not found")
text = text.replace(marker, helper + marker, 1)
text = text.replace(old_excerpt, excerpt, 1)
text = text.replace(test_marker, test + test_marker, 1)
path.write_text(text, encoding="utf-8")
